import SwiftUI
@_spi(Fixtures) import Tanrei

// specs/date-picker.spec.json in the gallery: each fixture is the open picker drawn in place (`TanreiDatePickerSurface`,
// DTP-1's verify) from its props (`presentation`, `mode`, `value`, `start`, `end`, `min`, `max`, `disabledDates`, `today`,
// `firstDayOfWeek`, `locale`, `entryMode`, `startView`, `label`) on a stage a phone row has room for — narrower and shorter
// than the spec's, so its cells narrow and a modal picker's calendar scrolls, as DTP-38 says. The days and years are generated by the picker
// (a fixture lists none). `fire` counts committed choices (change). Below them, a modal picker presented from a
// button and a docked picker below a text field opened by its calendar button, as a product writes them: the UI tests open
// them, choose a day and see them close.

extension GalleryComponent {
  static let datePicker = GalleryComponent(
    fixture: { fixture, fire in
      AnyView(GalleryDatePickerFixture(fixture: fixture, fire: fire))
    },
    explore: { _ in
      [
        GalleryExploration(
          title: "Date pickers opened from the page",
          examples: [
            GalleryExample(id: "presented", caption: "tap to open · OK fires") { fire in AnyView(GalleryPresentedDatePicker(fire: fire)) },
            GalleryExample(id: "anchored", caption: "calendar button · a day fires") { fire in AnyView(GalleryAnchoredDatePicker(fire: fire)) },
          ])
      ]
    },
    // The text-entry fixtures keep focus in their own fields: the row does not bind the gallery's `-focus`.
    managesFocus: true
  )
}

enum GalleryDatePickerStage {
  /// A phone row's room: seven cells about the minimum target.
  static let width: CGFloat = 304
  /// XCUITest reports a surface's frame with the drawing surface of its shadow: room for the modal container's, so that
  /// the row is wholly on screen.
  static let shadowRoom: CGFloat = 40
  /// Shorter than a modal picker: its calendar scrolls between its header and its actions (DTP-38), and the row fits a
  /// phone's first screen, which the accessibility audit needs.
  static let modalHeight: CGFloat = 440
  static let dockedHeight: CGFloat = 440
  /// The fixtures' `today` when a live picker has none: the fixtures' own.
  static let today = GalleryDatePickerDates.components("2026-09-24")
}

/// ISO 8601 calendar dates ("2026-09-17") as the picker takes them: year, month and day.
enum GalleryDatePickerDates {
  static func components(_ iso: String?) -> DateComponents? {
    guard let parts = iso?.split(separator: "-").compactMap({ Int($0) }), parts.count == 3 else { return nil }
    return DateComponents(year: parts[0], month: parts[1], day: parts[2])
  }

  static func text(_ components: DateComponents?) -> String {
    guard let year = components?.year, let month = components?.month, let day = components?.day else { return "" }
    return String(format: "%04d-%02d-%02d", year, month, day)
  }
}

/// One fixture, drawn in place from its props.
private struct GalleryDatePickerFixture: View {
  let fixture: GalleryFixture
  let fire: @MainActor () -> Void

  var body: some View {
    let docked = fixture.string("presentation") == "docked"
    let labels = TanreiDatePickerLabels(label: fixture.string("label") ?? TanreiDatePickerLabels().label)
    TanreiDatePickerSurface(
      presentation: TanreiDatePickerPresentation(named: fixture.string("presentation") ?? "modal"),
      mode: TanreiDatePickerMode(named: fixture.string("mode") ?? "single"), selection: GalleryDatePickerDates.components(fixture.string("value")),
      range: TanreiDateRange(start: GalleryDatePickerDates.components(fixture.string("start")), end: GalleryDatePickerDates.components(fixture.string("end"))),
      minDate: GalleryDatePickerDates.components(fixture.string("min")), maxDate: GalleryDatePickerDates.components(fixture.string("max")),
      disabledDates: Set((fixture.strings("disabledDates") ?? []).compactMap { GalleryDatePickerDates.components($0) }),
      today: GalleryDatePickerDates.components(fixture.string("today")),
      firstDayOfWeek: TanreiDatePickerFirstDayOfWeek(named: fixture.string("firstDayOfWeek") ?? "locale"),
      locale: fixture.string("locale").map { Locale(identifier: $0) },
      entryMode: TanreiDatePickerEntryMode(named: fixture.string("entryMode") ?? "calendar"),
      startView: TanreiDatePickerStartView(named: fixture.string("startView") ?? "day"), labels: labels,
      onChange: { _, _ in fire() }
    )
    .frame(width: GalleryDatePickerStage.width, height: docked ? GalleryDatePickerStage.dockedHeight : GalleryDatePickerStage.modalHeight)
    .padding(.horizontal, docked ? .zero : GalleryDatePickerStage.shadowRoom)
  }
}

/// A button that presents a modal picker, as a product writes one; OK fires when the choice changed. Its value is the chosen
/// date.
private struct GalleryPresentedDatePicker: View {
  let fire: @MainActor () -> Void
  @State private var isPresented = false
  @State private var date = GalleryDatePickerDates.components("2026-09-17")

  var body: some View {
    TanreiButton("Due date", variant: .outlined, action: { isPresented = true })
      .accessibilityValue(GalleryDatePickerDates.text(date))
      .tanreiDatePicker(
        isPresented: $isPresented,
        selection: Binding(
          get: { date },
          set: {
            date = $0
            fire()
          }), today: GalleryDatePickerStage.today, locale: Locale(identifier: "en-US"))
  }
}

/// A text field with a calendar button in its trailing slot that opens a docked picker below it, as a product's date field
/// does (TXF-22: the button is its own focus stop after the input); a chosen day fires and is written into the field.
private struct GalleryAnchoredDatePicker: View {
  let fire: @MainActor () -> Void
  @State private var isPresented = false
  @State private var text = ""

  var body: some View {
    TanreiTextField("Check-in", text: $text, prompt: Text(verbatim: "yyyy-mm-dd")) {
      EmptyView()
    } trailingIcon: {
      TanreiIconButton("Choose a date", action: { isPresented = true }) { Image(systemName: "calendar") }
    }
    .frame(width: GalleryDatePickerStage.width)
    .tanreiDatePicker(
      isPresented: $isPresented,
      selection: Binding(
        get: { GalleryDatePickerDates.components(text) },
        set: {
          text = GalleryDatePickerDates.text($0)
          fire()
        }), presentation: .docked, today: GalleryDatePickerStage.today, locale: Locale(identifier: "en-US"))
    // The docked picker is drawn in the field's overlay, above what follows the anchor in its own container only: room
    // for it below, in the row.
    .padding(.bottom, GalleryDatePickerStage.dockedHeight)
  }
}
